fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Ensure the string is non-empty
    if txt.len() == 0 {
        return false;
    }

    // Get the last character
    let last_char = txt.chars().last().unwrap();

    // Check if the last character is an ASCII letter
    if !last_char.is_ascii_alphabetic() {
        return false;
    }

    // Check if the last character is standalone
    if txt.len() == 1 {
        return true; // The last character is standalone if it's the only character
    }

    // Check the character before the last
    let second_last_char = txt.chars().nth(txt.len() - 2).unwrap();
    if second_last_char == ' ' {
        return true; // The last character is standalone if the second last is a space
    }

    // If none of the conditions are met, return false
    false
}